#!/usr/bin/env bash
# Fail if any declared pnpm override is not actually in force in the lockfile.
#
# WHY THIS EXISTS
# Every transitive-CVE fix in this repo is a `pnpm.overrides` entry. Those entries can stop
# working with no visible signal, in three separate ways, all of which have happened here:
#
#   1. A lockfile regenerated by the wrong pnpm silently DROPS the `overrides:` block.
#      (renovatebot/renovate#43161, May 2026 - pnpm@latest moved to 11.x and Renovate
#      rewrote locks without overrides, restoring uuid@8.3.2 among others.)
#   2. Overrides declared in a workspace MEMBER are ignored - pnpm honours them only at a
#      workspace root - so they read as applied and do nothing.
#   3. A `package.json` `pnpm.overrides` block SHADOWS `pnpm-workspace.yaml` overrides, so
#      adding one entry can silently disable every other pin in the repo.
#
# A green build with a stripped override block is strictly worse than a red one: the repo
# looks patched and is not. This check makes that state fail loudly.
#
# Usage: verify-overrides.sh [root]     (defaults to the current directory)
set -uo pipefail
ROOT="${1:-.}"
status=0
checked=0

# semver-ish compare: is $1 >= $2 ?
ge() { [ "$(printf '%s\n%s\n' "$2" "$1" | sort -V | head -1)" = "$2" ]; }

# pnpm range selectors used by the floor overrides in this repository.
# Unknown syntax fails the gate rather than silently skipping a declared pin.
matches_selector() {
  local version="$1" selector="$2" term bound
  [ -z "$selector" ] && return 0
  for term in $selector; do
    case "$term" in
      '>='*) bound="${term#>=}"; ge "$version" "$bound" || return 1 ;;
      '<='*) bound="${term#<=}"; ge "$bound" "$version" || return 1 ;;
      '>'*) bound="${term#>}"; ge "$version" "$bound" && [ "$version" != "$bound" ] || return 1 ;;
      '<'*) bound="${term#<}"; ge "$bound" "$version" && [ "$version" != "$bound" ] || return 1 ;;
      *)
        if [[ "$term" =~ ^[0-9]+$ ]]; then
          [ "${version%%.*}" = "$term" ] || return 1
        elif [[ "$term" =~ ^[0-9]+\.[0-9]+\.[0-9]+$ ]]; then
          [ "$version" = "$term" ] || return 1
        else
          return 2
        fi ;;
    esac
  done
}

while IFS= read -r lock; do
  dir=$(dirname "$lock")
  pj="$dir/package.json"
  [ -f "$pj" ] || continue

  # Overrides can live in either place. pnpm-workspace.yaml is only consulted when
  # package.json has no pnpm.overrides block (package.json wins and shadows it).
  keys=$(jq -r '(.pnpm.overrides // {}) | keys[]' "$pj" 2>/dev/null)
  src="package.json"
  if [ -z "$keys" ] && [ -f "$dir/pnpm-workspace.yaml" ]; then
    keys=$(awk '/^overrides:/{f=1;next} /^[^[:space:]]/{f=0} f && /:/ {sub(/:.*/,"");gsub(/^[[:space:]]+|['"'"'"]/,"");print}' "$dir/pnpm-workspace.yaml")
    src="pnpm-workspace.yaml"
  fi
  [ -z "$keys" ] && continue

  echo "== $dir (overrides declared in $src)"
  checked=$((checked+1))

  if ! grep -q '^overrides:' "$lock"; then
    echo "   FAIL: $lock has no 'overrides:' block — every pin in this directory is INERT."
    echo "         A lockfile regenerated by the wrong pnpm strips this silently."
    status=1
    continue
  fi

  while IFS= read -r key; do
    [ -z "$key" ] && continue
    if [ "$src" = "package.json" ]; then
      want=$(jq -r --arg k "$key" '.pnpm.overrides[$k]' "$pj")
    else
      want=$(awk -v k="$key" '/^overrides:/{f=1;next} /^[^[:space:]]/{f=0} f' "$dir/pnpm-workspace.yaml" \
             | grep -E "^[[:space:]]*['\"]?${key}['\"]?:" | head -1 | sed -E "s/.*:[[:space:]]*//; s/^['\"]//; s/['\"]$//")
    fi
    case "$want" in ">="*) ;; *) continue ;; esac   # only floors are checkable
    floor=$(printf '%s' "$want" | sed -E 's/^>=([^ ]+).*/\1/')

    # A parent delimiter precedes a package name, unlike the > in >= ranges.
    pkg=$(printf '%s' "$key" | sed -E 's/^.*>(@?[a-zA-Z])/\1/')
    selector=""
    if [[ "$pkg" =~ ^(@[^/]+/[^@]+|[^@]+)@(.*)$ ]]; then
      selector="${BASH_REMATCH[2]}"
      pkg="${BASH_REMATCH[1]}"
    fi

    vers=$(grep -oE "^  '?${pkg}@[0-9]+\.[0-9]+\.[0-9]+" "$lock" 2>/dev/null \
           | grep -oE '[0-9]+\.[0-9]+\.[0-9]+' | sort -uV)
    [ -z "$vers" ] && { echo "   ok   $key (not installed here)"; continue; }

    for version in $vers; do
      matches_selector "$version" "$selector"
      applies=$?
      if [ "$applies" = 2 ]; then
        echo "   FAIL: $key uses an unsupported selector; cannot verify its floor."
        status=1
        break
      fi
      [ "$applies" = 0 ] || continue
      if ! ge "$version" "$floor"; then
        echo "   FAIL: $key resolves $version BELOW its floor $floor."
        status=1
      fi
    done
    echo "   checked $key >= $floor (resolved $(printf '%s' "$vers" | tr '\n' ' '))"

  done <<< "$keys"
done < <(find "$ROOT" -name pnpm-lock.yaml -not -path '*/node_modules/*' 2>/dev/null | sort)

echo
if [ "$checked" = "0" ]; then
  echo "No pnpm overrides declared anywhere — nothing to verify."
elif [ "$status" = "0" ]; then
  echo "All supported override floors are in force; non-floor pins are not checked here."
else
  echo "One or more overrides are NOT in force. This repo is not patched the way it claims."
fi
exit "$status"
